mapper.select:
select a.id ,a.condition_number as conditionNumber ,b.api_code as apiCode ,a.name ,a.status ,content_show as contentShow ,date_format(a.create_time,'%Y-%m-%d %T') as createTime ,date_format(a.update_time,'%Y-%m-%d %T') as updateTime from b_score_search_condition as a left join b_score_search_condition_mapping as b on b.condition_id = a.id where a.condition_type = 1 and a.is_del = 1 and b.is_del = 1
and b.api_code = #{apiCode}
and a.name = #{name}
and a.status = #{status}
order by a.update_time desc

select count(*)
from b_score_search_condition as a
left join b_score_search_condition_mapping as b on b.condition_id = a.id
where a.condition_type = 1 and a.is_del = 1 and b.is_del = 1

    and b.api_code = #{apiCode}


    and a.name = #{name}


    and a.status = #{status}
